"""困难发言安排与真倾听最小对照，不覆盖已有冻结数据。"""
from pathlib import Path
import json
R=Path(__file__).resolve().parent;D=R/'数据/companion_v24_turn_hard';assert not D.exists();D.mkdir()
items=[('友谊',['我觉得朋友之间可以亲近，也要给彼此保留空间，坦诚比一味迎合更珍贵呀。','我觉得友谊里的可靠很重要，答应的事尽量做到，做不到也愿意坦诚说明。','我觉得朋友不必所有看法都相同，愿意理解差异也能让关系更自在。','我觉得友谊可以在小事里慢慢积累，不必每次聊天都特别热闹呀。']),('散步',['我觉得散步能让人注意到路边的小变化，不必总把它当成锻炼任务呀。','我觉得散步适合放慢节奏，不过天气和路线也会影响舒服程度。','我觉得一起散步可以边走边聊，也可以安静走一会儿，舒服就好呀。','我觉得散步的趣味常在过程里，同一条路不同时间也会不一样。']),('看书',['我觉得读书能遇到新的想法，不必每本都读完，找到喜欢的部分也很好。','我觉得书里的观点可以认真想，也不必全盘接受，保留自己的判断很重要。','我觉得看书不需要比谁读得多，慢慢理解一段文字也很有价值呀。','我觉得一本书是否适合，可以先看几页，读不进去也允许换一本呀。']),('养花',['我觉得养花能看到缓慢的变化，但也要了解光照和浇水需求。','我觉得养花的乐趣在照顾过程里，不只是等开花的结果呀。','我觉得养花需要一点耐心，偶尔没养好不等于不认真，可以调整方法。','我觉得养花可以从容易照顾的一盆开始，不必一下摆满整个房间。']),('旅行',['我觉得旅行可以认识不同生活方式，也要留出休息和意外安排的余地。','我觉得旅行不必把景点排满，慢慢走反而能留下更具体的记忆呀。','我觉得旅行里新鲜感和不便都会有，期待之外也可以接受小小变化。','我觉得旅行可以按自己的兴趣来，不必照着别人的必去清单跑。']),('音乐',['我觉得音乐能陪着不同心情，但每个人觉得舒服的声音会不同呀。','我觉得听音乐不必追着热门榜，喜欢一首旧歌也很自然。','我觉得音乐的节奏能影响氛围，安静时轻一点，热闹时也可以明快些。','我觉得音乐值得慢慢听，偶尔注意歌词，偶尔只感受旋律都很好。']),('做饭',['我觉得做饭有创作乐趣，也有日常辛苦，简单做一道喜欢的菜就很好。','我觉得做饭不必次次成功，口味可以慢慢调整，安全和卫生先照顾好。','我觉得做饭可以按时间安排，不必为了丰盛把自己弄得很累呀。','我觉得自己做饭能选择食材和口味，偶尔买现成的也很正常。']),('独处',['我觉得独处和孤单不完全相同，一个人也可以安排舒服的生活。','我觉得独处可以给思绪留空间，但需要交流时也可以主动找朋友呀。','我觉得独处不必变成自我提升任务，安静待着也可以。','我觉得独处适不适合取决于当时的需要，不必用一种方式概括所有人。'])]
forms=['你听我说这个安排：现在先由你聊看法，我暂时不发表意见。','我说想听是想听你的观点，不是叫你继续听我的话呀。','不是要你说明谁先说，是要你实际说出对这个主题的意见。','你先讲具体观点，不要仅仅回复明白了，也别让我替你发表意见。']
rows=[]
def add(h,a,c):rows.append({'id':f'hard_train_{len(rows):03}','history':h,'response_text':a,'emotion_label':'neutral','category':c})
for t,answers in items:
 for i,q in enumerate(forms):
  add([{'role':'user','content':f'聊聊{t}吧。'},{'role':'assistant','content':'你说吧，我听着。'},{'role':'user','content':q}],answers[i],'困难纠正实际观点')
  # 只改变发言安排，不能因听字触发相同目标。
  other=['你听我说这个安排：现在我先聊自己的想法，你暂时不发表意见。','我说想讲是想让你听我的观点，不是叫你给我意见呀。','不是要你讲道理，是要你让我先说完对这个主题的想法。','我先说具体想法，你暂时别抢着发表意见，先听完再说。'][i]
  add([{'role':'user','content':f'聊聊{t}吧。'},{'role':'assistant','content':answers[i]},{'role':'user','content':other}],['好呀，你慢慢讲，我先听完。','好呀，这次你来说，我认真听着。','明白啦，你先说完，我不急着插话。','好呀，你把想法慢慢说完，我先听。'][i],'最小对照用户发言')
old=[json.loads(x) for x in (R/'数据/companion_v24_affection/train.jsonl').read_text(encoding='utf8').splitlines()]
for x in old:rows.append({**x,'id':f'hard_replay_{len(rows):03}'})
dev=[]
for t,a in [('写日记','我觉得写日记能留下当时的想法，不用要求每篇都好看，也不必天天写呀。'),('整理房间','我觉得整理能让东西好找，但不必要求房间始终完美，适合日常使用就很好。'),('跑步','我觉得跑步可以释放压力，不过循序渐进比一味追速度更重要。'),('拍照','我觉得照片能留住当时的样子，不过不必为了拍照错过眼前的体验呀。')]:
 for q in ['我负责听，你负责讲；先给我一个关于刚才主题的判断。','听着，下面的分工是你表达观点，我听，不是让我讲。','请你来谈看法，不要把这句话当成我要求倾诉。','别再解释发言顺序啦，把你的具体想法说出来。']:
  dev.append({'id':f'hard_dev_{len(dev):03}','history':[{'role':'user','content':f'聊聊{t}吧。'},{'role':'assistant','content':'你想说什么都可以，我在听。'},{'role':'user','content':q}],'response_text':a,'emotion_label':'neutral'})
for n,data in [('train',rows),('dev',dev)]: (D/(n+'.jsonl')).write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in data),encoding='utf8')
(D/'style.txt').write_text((R/'体验/陪伴提示.txt').read_text(encoding='utf8'),encoding='utf8')
print('训练',len(rows),'开发',len(dev))
